"""Generated by solo-to-scale; edit `templates/tools/test_area.py` in the plugin, then run upgrade.

Run only the tests for one area during a session; CI runs the full suite.

  python tools/test_area.py <path> [extra pytest args]   # also: make test-area AREA=<path>

If <path> holds test files, pytest runs on it. Otherwise it runs the repo's tests whose file names
mention the area's name (for example `tools/claim.py` -> tests matching `claim`).
"""
from __future__ import annotations

import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def targets(area: str, root: Path = ROOT) -> list[str]:
    p = (root / area).resolve()
    if p.is_dir() and any(p.rglob("test_*.py")):
        return [str(p)]
    if p.is_file() and p.name.startswith("test_"):
        return [str(p)]
    stem = p.stem if p.suffix else p.name
    found = sorted({str(t) for t in root.rglob(f"test_*{stem}*.py") if ".git" not in t.parts})
    return found


def main(argv: list[str] | None = None) -> int:
    argv = list(sys.argv[1:] if argv is None else argv)
    if not argv:
        print("usage: python tools/test_area.py <path> [pytest args]")
        return 2
    found = targets(argv[0])
    if not found:
        print(f"no tests found for {argv[0]}; add some, or run the full suite")
        return 5
    return subprocess.call([sys.executable, "-m", "pytest", "-q", *found, *argv[1:]], cwd=ROOT)


if __name__ == "__main__":
    sys.exit(main())
